settings.custom_liquid:
{%- assign v = product.selected_or_first_available_variant -%}
{%- if v.compare_at_price > v.price -%}<p class="sn-pdp-save">Du sparst <b>{{ v.compare_at_price | minus: v.price | money }}</b> ({{ v.compare_at_price | minus: v.price | times: 100 | divided_by: v.compare_at_price }} %)</p>{%- endif -%}
{%- assign sn_left = 4400 | minus: cart.total_price | minus: v.price -%}
<p class="sn-pdp-ship">{% render 'schnappy-icon', icon: 'truck' %}{%- if sn_left > 0 -%}<span>Noch <b>{{ sn_left | money }}</b> bis zum <b>Gratis-Versand</b></span>{%- else -%}<span>Mit diesem Artikel: <b>Gratis-Versand</b></span>{%- endif -%}</p>
{%- if v.available -%}<p class="sn-instock sn-instock--lg"><i aria-hidden="true"></i>Sofort lieferbar</p>{%- endif -%}
